wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(175615968609484680)
,p_name=>'PE.PROPERTY.AUTOM_CONDITION_JS_EXPRESSION_BOOLEAN.EXAMPLES'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'<dl><dt>To return successfully when the employee is in department 30 or is a manager:</dt>',
'<dd><pre>',
'( apex.env.P2_DEPTNO === "30" || apex.env.P2_JOB === "MANAGER" )',
'</pre></dd>',
'</dl>'))
,p_version_scn=>37166067046489
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(242767838449661473)
,p_name=>'PE.PROPERTY.AUTOM_CONDITION_JS_EXPRESSION_BOOLEAN.PROMPT'
,p_message_text=>'JavaScript Expression'
,p_version_scn=>37166067046489
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(175616147363484681)
,p_name=>'PE.PROPERTY.AUTOM_CONDITION_JS_FUNC_BODY_BOOLEAN.EXAMPLES'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'<dl><dt>To return successfully when the employee is in department 30:</dt>',
'<dd><pre>',
'let deptno,',
'    rows;',
'',
'rows = apex.conn.execute( "select deptno from emp empno = :1", [ apex.env.P2_EMPNO ] ).rows;',
'for (let row of rows) {',
'  deptno = row.DEPTNO;',
'}',
'',
'return ( deptno === 30 );',
'</pre></dd>',
'</dl>'))
,p_version_scn=>37166067046489
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(242768705057661474)
,p_name=>'PE.PROPERTY.AUTOM_CONDITION_JS_FUNC_BODY_BOOLEAN.PROMPT'
,p_message_text=>'JavaScript Function Body'
,p_version_scn=>37166067046489
);
