,p_name=>'PE.PROPERTY.DA_EXECUTION_TYPE.LOV.DEBOUNCE.HELP'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Actions are only executed once after a specified time at the end of a single or series of events.</p>',
'        <p>Example 1:</p>',
'        <p>Update a text field if the user has stopped typing for 2 seconds and use the values last entered.</p>',
'        <p>Example 2:</p>',
'        <p>Refresh a region once after a click and ignore all other clicks in the next 5 seconds.</p>'))
,p_version_scn=>37166067046336
);
