,p_name=>'PE.PROPERTY.FILTER_OPERATORS.LOV.C.D'
,p_message_text=>'Contains'
,p_version_scn=>37166067046364
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(404762010067249712)
,p_name=>'PE.PROPERTY.FILTER_OPERATORS.LOV.C.HELP'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Filter returns results of column values containing the filter value.',
'        &PRODUCT_NAME. will utilize a <code>column LIKE <strong>%</strong>filtervalue<strong>%</strong></code> in the where clause.</p>',
'        <p>Note - this operator will prevent any column indexes being used, which may result in a full table scan.</p>'))
,p_version_scn=>37166067046364
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(245982907283481153)
,p_name=>'PE.PROPERTY.FILTER_OPERATORS.LOV.CASE_INSENSITIVE.D'
,p_message_text=>'Case Insensitive'
,p_version_scn=>37166067046364
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(373631815256681177)
,p_name=>'PE.PROPERTY.FILTER_OPERATORS.LOV.CASE_INSENSITIVE.HELP'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Filter returns results of column values irrespective of differences in the case of the column value and filter value.',
'        &PRODUCT_NAME. will utilize a <code>UPPER(column) <em>operator</em> UPPER(filtervalue)</code> in the where clause.</p>',
'        <p>Note - Generally performing UPPER on both the column and filter value will prevent the use of any column indexes, except for function based column indexes with UPPER(<em>column</em>).</p>'))
,p_version_scn=>37166067046364
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(245982862334481152)
,p_name=>'PE.PROPERTY.FILTER_OPERATORS.LOV.REGEXP.D'
,p_message_text=>'Regular Expression'
,p_version_scn=>37166067046364
);
