wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(1604035880784550)
,p_name=>'PE.PROPERTY.JET_REFERENCE_LINE_COLORS.COMPONENT_PROPERTY.JET_CHART_SERIES.ACCESSIBILITY_HELP_TEXT'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Enhancing chart accessibility through mindful color selection and compliance with WCAG standards is crucial for ensuring inclusivity in data visualization.</p>',
'<strong>Best Practices:</strong>',
'<ol>',
'<li><strong>Use Bold and Clear Colors:</strong> Opt for colors that are bold and clear to ensure both text and graphical elements within your charts are easily distinguishable. This enhances readability and comprehension for all users, including thos'
||'e with visual impairments.</li>',
'<li><strong>Check Color Contrast Ratio:</strong> Utilize contrast checking tools to evaluate the color contrast ratio between foreground and background colors. Aim for a ratio of at least 4.5:1 to ensure readability for individuals with varying level'
||'s of vision impairment.</li>',
'</ol>'))
,p_version_scn=>12412759
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(75492463823453812)
,p_name=>'PE.PROPERTY.JET_REFERENCE_LINE_COLORS.EXAMPLES'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'<dl>',
'<dt>A comma delimited list of colors:</dt>',
'<dd><pre>',
'<strong>red,yellow,blue</strong>',
'</pre></dd>',
'<dt>A comma delimited list of page or application items, returning colors, using:</dt>',
'<dd><pre>',
'<code>&amp;ITEM.</code> syntax. For example, <strong><code>&amp;ITEM_1.</code>,<code>&amp;ITEM_2.</code>,<code>&amp;ITEM_3.</code></strong>',
'</pre></dd>',
'<dt>A comma delimited list of columns, returning colors, using:</dt>',
'<dd><pre>',
'<code>&amp;COLUMN_NAME.</code> syntax. For example, <strong><code>&amp;COLUMN_NAME_1.</code>,<code>&amp;COLUMN_NAME_2.</code>,<code>&amp;COLUMN_NAME_3.</code></strong>',
'</pre></dd>',
'</dl>'))
,p_version_scn=>37166067046381
);
