wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(175607458774484622)
,p_name=>'PE.PROPERTY.READ_ONLY_CONDITION_JS_EXPRESSION_BOOLEAN.EXAMPLES'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'<dl><dt>To return successfully when the employee is in department 30 or is a manager:</dt>',
'<dd><pre>',
'( apex.env.P2_DEPTNO === "30" || apex.env.P2_JOB === "MANAGER" )',
'</pre></dd>',
'</dl>'))
,p_version_scn=>37166067046470
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(600264234470090586)
