,p_name=>'PE.PROPERTY.READ_ONLY_CONDITION_TYPE.COMPONENT_PROPERTY.REGION.HELP'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Select a condition type that must be met in order for this region to render page items as read-only.',
'Not selecting a condition causes the page items to render normally.</p>',
'<p>Note: If you want a page item in this region (for example a search field) to always render as an enterable page item, independent of how this condition evaluates, then you should set the read only condition of that page item to "Never" to overwrit'
||'e the region setting.</p>'))
,p_version_scn=>37166067046508
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(123126530789211841)
,p_name=>'PE.PROPERTY.READ_ONLY_CONDITION_TYPE.HELP'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Select a condition type that must be met in order for this page to render page items as read only. Not selecting a condition causes the page items to render normally.',
'The read only condition is evaluated after executing the processes with a processing point of <em>Before Header</em>.</p>',
'<p>Note: If you want some page items (for example a search field) or all page items of a specific region to always render as enterable page items independent of how this condition evaluates, then set the read only condition of those regions/page item'
||'s to <strong>Never</strong> to overwrite the parent setting.</p>'))
,p_version_scn=>37166067046470
);
