);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(175614360101484673)
,p_name=>'PE.PROPERTY.SHORTCUT_PLSQL_FUNC_BODY_VARCHAR2.EXAMPLES'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'<dl><dt>To return YES when the employee is in department 30:</dt>',
'<dd><pre>',
'declare',
'    l_deptno number;',
'begin',
'    select deptno',
'      into l_deptno',
'      from emp',
'     where empno = :P2_EMPNO;',
'',
'    if l_deptno = 30 then',
'        return ''YES'';',
'    else',
'        return ''NO'';',
'    end if;',
'end;',
'</pre></dd>',
'</dl>'))
,p_version_scn=>37166067046484
);
