,p_attribute_group_id=>wwv_flow_imp.id(6038497365653879)
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Example: Template to render the default search result layout.</p>',
'<pre>',
'&lt;div class="a-ResultsItem &amp;RESULT_CSS_CLASSES!ATTR."&gt;',
'  {if ?ICON_VALUE/}',
'    {case ICON_TYPE/}',
'      {when INITIALS/}',
'        &lt;div class="a-ResultItem-initials u-color-var"&gt;&amp;ICON_VALUE.&lt;/div&gt;',
'      {when URL/}',
'        &lt;div class="a-ResultItem-image"&gt;&lt;img src="&amp;ICON_VALUE!ATTR." alt="&amp;TITLE!ATTR." role="presentation" /&gt;&lt;/div&gt;',
'      {when CLASS/}',
'        &lt;div class="a-ResultItem-icon u-color-var"&gt;&lt;span class="fa &amp;ICON_VALUE!ATTR." aria-hidden="true"&gt;&lt;/span&gt;&lt;/div&gt;',
'    {endcase/}',
'  {endif/}',
'  &lt;div class="a-ResultsItem-content"&gt;',
'    &lt;div class="a-ResultsItem-header"&gt;',
'      {if ?LINK/}',
'        &lt;span class="a-ResultsItem-title"&gt;&lt;a href="&amp;LINK!ATTR."&gt;&amp;TITLE.&lt;/a&gt;&lt;/span&gt;',
'      {else/}',
'        &lt;span class="a-ResultsItem-title"&gt;&amp;TITLE.&lt;/span&gt;',
'      {endif/}',
'      {if ?BADGE/}&lt;span class="a-ResultsItem-badge"&gt;&amp;BADGE.&lt;/span&gt;{endif/}',
'    &lt;/div&gt;',
'    {if ?SUBTITLE/}&lt;div class="a-ResultsItem-subTitle"&gt;&amp;SUBTITLE.&lt;/div&gt;{endif/}',
'    {if ?DESCRIPTION/}&lt;div class="a-ResultsItem-description"&gt;&amp;DESCRIPTION.&lt;/div&gt;{endif/}',
'    {if ?HAS_CUSTOM_ATTRS/}',
'      &lt;div class="a-ResultsItem-attributes"&gt;',
'        {if ?CUSTOM_01/}&lt;span class="a-ResultsItem-attribute"&gt;&amp;CUSTOM_01.&lt;/span&gt;{endif/}',
'        {if ?CUSTOM_02/}&lt;span class="a-ResultsItem-attribute"&gt;&amp;CUSTOM_02.&lt;/span&gt;{endif/}',
'        {if ?CUSTOM_03/}&lt;span class="a-ResultsItem-attribute"&gt;&amp;CUSTOM_03.&lt;/span&gt;{endif/}',
'      &lt;/div&gt;',
'    {endif/}',
'    {if ?LAST_MODIFIED/}&lt;div class="a-ResultsItem-misc"&gt;&amp;LAST_MODIFIED.&lt;/div&gt;{endif/}',
'  &lt;/div&gt;',
'&lt;/div&gt;',
'</pre>'))
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'Enter HTML Expression to display a search result row. Use <code>&COLUMN.</code> syntax to show search result column values in HTML. Supports template directives. The following substitutions are available:',
'</p>',
'<dl>',
'<dt>TITLE</dt>',
'<dd><strong>Title</strong> column.</dd>',
'<dt>SUBTITLE</dt>',
'<dd><strong>Subtitle</strong> column.</dd>',
'<dt>PRIMARY_KEY_1</dt>',
'<dd><strong>Primary Key</strong> column.</dd>',
'<dt>PRIMARY_KEY_2</dt>',
'<dd>Second <strong>Primary Key</strong> column.</dd>',
'<dt>DESCRIPTION</dt>',
'<dd><strong>Description</strong> column.</dd>',
'<dt>BADGE</dt>',
'<dd><strong>Badge</strong> column.</dd>',
'<dt>LAST_MODIFIED</dt>',
'<dd><strong>Last Modified</strong> column. The <strong>Last Modified Format Mask</strong> will be applied to this column, if specified.</dd>',
'<dt>CUSTOM_01</dt>',
'<dd><strong>Custom #1</strong> column.</dd>',
'<dt>CUSTOM_02</dt>',
'<dd><strong>Custom #2</strong> column.</dd>',
'<dt>CUSTOM_03</dt>',
'<dd><strong>Custom #3</strong> column.</dd>',
'<dt>SCORE</dt>',
'<dd><strong>Score</strong> column. For Oracle TEXT Search Configurations, this will be the score returned by Oracle TEXT; other configurations allow to map a query column.</dd>',
'<dt>ICON_TYPE</dt>',
'<dd>Represents the icon type: Can be <strong>CLASS</strong>, <strong>URL</strong> or <strong>INITIALS</strong>.</dd>',
'<dt>ICON_VALUE</dt>',
'<dd>The actual icon value, depending on the value of <strong>ICON_TYPE</strong></dd>',
'<dt>RESULT_CSS_CLASSES</dt>',
'<dd>The CSS classes to be applied to each row, based on the <strong>Result CSS Classes</strong> Search Configuration attribute.</dd>',
'<dt>LINK</dt>',
'<dd>The <strong>link</strong> being specified in the search configuration.</dd>',
'<dt>CONFIG_ID</dt>',
'<dd>Internal ID of the search configuration.</dd>',
'<dt>CONFIG_LABEL</dt>',
'<dd>Label of the search configuration.</dd>',
'</dl>'))
);
