 p_id=>wwv_flow_imp.id(1604343648052038)
,p_plugin_id=>wwv_flow_imp.id(1603669291043434)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_prompt=>'Run in Background'
,p_attribute_type=>'CHECKBOX'
,p_is_required=>false
,p_default_value=>'N'
,p_is_translatable=>false
,p_help_text=>'Specify whether to execute this chain in the background.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(1604635608063659)
,p_plugin_id=>wwv_flow_imp.id(1603669291043434)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>2
,p_display_sequence=>40
,p_prompt=>'Serialize'
,p_attribute_type=>'CHECKBOX'
,p_is_required=>false
,p_default_value=>'N'
,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(1604343648052038)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'Y'
,p_attribute_group_id=>wwv_flow_imp.id(1461486944563690)
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Specify whether to serialize executions of this execution chain. When set to <strong>On</strong>, all executions (from all APEX sessions) with the same <strong>Context Value</strong> will be serialized, to avoid concurrent executions in the backgr'
||'ound. An execution with a NULL context value will block executions regardless of the context value, and a new execution with a NULL context value will only run, if <em>no other execution</em> of this process is running.</p>',
'<p> Use this setting when processes of this chain are likely to work on the same resources, for instance, performing DML on the same row in a table.</p>'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(1604929538071687)
,p_plugin_id=>wwv_flow_imp.id(1603669291043434)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>3
,p_display_sequence=>20
,p_prompt=>'Return ID into Item'
,p_attribute_type=>'PAGE ITEM'
,p_is_required=>false
,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(1604343648052038)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'Y'
,p_help_text=>'Choose a page item to return the execution ID into. Based on the execution ID, the current status of the background execution can be fetched.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(1605279278074176)
,p_plugin_id=>wwv_flow_imp.id(1603669291043434)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>4
,p_display_sequence=>60
,p_prompt=>'Temporary File Handling'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'IGNORE'
,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(1604343648052038)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'Y'
,p_lov_type=>'STATIC'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>To execute this chain in the background, &PRODUCT_NAME. clones the current APEX session; and all background executions will work with the session clone.</p>',
'<p>Determine how to deal with temporary files, uploaded through a <strong>File Browse</strong> page item.</p>'))
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(1605593771077410)
,p_plugin_attribute_id=>wwv_flow_imp.id(1605279278074176)
,p_display_sequence=>10
,p_display_value=>'Ignore'
,p_return_value=>'IGNORE'
,p_help_text=>'Neither move nor copy temporary files to the <em>working session</em> for background execution. Choose this option if the background processes will not work with uploaded files.'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(1605949077078549)
,p_plugin_attribute_id=>wwv_flow_imp.id(1605279278074176)
,p_display_sequence=>20
,p_display_value=>'Move'
,p_return_value=>'MOVE'
,p_help_text=>'Move temporary files to the <em>working session</em> for background execution. Choose this option if access to temporary files is only needed by <em>one</em> background execution chain.'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(1606398394079365)
,p_plugin_attribute_id=>wwv_flow_imp.id(1605279278074176)
,p_display_sequence=>30
,p_display_value=>'Copy'
,p_return_value=>'COPY'
,p_help_text=>'Copy temporary files to the <em>working session</em> for background execution. Choose this option  if you have multiple background execution chains, and all of them require access to the temporary files.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(1607812256110222)
,p_plugin_id=>wwv_flow_imp.id(1603669291043434)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>5
,p_display_sequence=>70
,p_prompt=>'Temporary File Items'
,p_attribute_type=>'PAGE ITEMS'
,p_is_required=>false
,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(1605279278074176)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'IN_LIST'
,p_depending_on_expression=>'MOVE,COPY'
,p_help_text=>'Specify a list of page items to move or copy to the session clone for this background execution. If nothing is selected, all temporary files are affected.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(1608115916120274)
,p_plugin_id=>wwv_flow_imp.id(1603669291043434)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>6
,p_display_sequence=>80
,p_prompt=>'Executions Limit'
,p_attribute_type=>'NUMBER'
,p_is_required=>false
,p_display_length=>5
,p_max_length=>5
,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(1604343648052038)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'Y'
,p_help_text=>'If an execution limit is specified, &PRODUCT_NAME. will raise an error message, if an application user requests more than the specified limit of background executions within the current session. For instance, if a value of <strong>3</strong> is speci'
||'fied, end users see an error message when attempting to submit the fourth background execution. This is useful to prevent users from submitting large amounts of background executions to the server.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(1383441235481930)
,p_plugin_id=>wwv_flow_imp.id(1603669291043434)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>7
,p_display_sequence=>30
,p_prompt=>'Context Value Item'
,p_attribute_type=>'PAGE ITEM'
,p_is_required=>false
,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(1604343648052038)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'Y'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Pick a page item containing a <em>Context Value</em> to be passed to the background execution. The context value is available in the <strong>APEX_APPL_PAGE_BG_PROC_STATUS</strong> view, as well as in the record returned from <strong>APEX_BACKGROUN'
||'D_PROCESS.GET_EXECUTION</strong>.</p>',
'<p>When the <strong>Serialize</strong> switch is enabled, the context value will be used as the <em>mutex</em> for serialization, which means that executions with the same context value have to wait for each other, while executions with different con'
||'text values can run in parallel.</p>'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(1383788116475849)
,p_plugin_id=>wwv_flow_imp.id(1603669291043434)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>8
,p_display_sequence=>50
,p_prompt=>'When Already Running'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'WAIT'
,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(1604635608063659)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'Y'
,p_lov_type=>'STATIC'
,p_attribute_group_id=>wwv_flow_imp.id(1461486944563690)
,p_help_text=>'Specify the behavior when a background execution is added, while another execution with the same or a NULL <em>context value</em> is already running.'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(1384062064473544)
,p_plugin_attribute_id=>wwv_flow_imp.id(1383788116475849)
,p_display_sequence=>10
,p_display_value=>'Wait'
,p_return_value=>'WAIT'
,p_help_text=>'The execution will wait until previous executions have finished.'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(1384439479470970)
,p_plugin_attribute_id=>wwv_flow_imp.id(1383788116475849)
,p_display_sequence=>20
,p_display_value=>'Error'
,p_return_value=>'ERROR'
,p_help_text=>'If an execution with the same context value is already running, an error is raised.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(1384915422456178)
,p_plugin_id=>wwv_flow_imp.id(1603669291043434)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>9
,p_display_sequence=>90
,p_prompt=>'Submit Immediately'
,p_attribute_type=>'CHECKBOX'
,p_is_required=>false
,p_default_value=>'N'
,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(1604343648052038)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'Y'
,p_help_text=>'Enable this switch if the background process should be submitted for execution <em>immediately</em>, outside of the current transaction. If the current transaction is rolled back, the submitted execution remains in the queue. When disabled, the backg'
||'round process submission will be part of the current transaction.'
);
end;
