prompt --application/shared_components/plugins/web_source_type/http
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(1677862467038200)
,p_plugin_type=>'WEB SOURCE TYPE'
,p_name=>'HTTP'
,p_display_name=>'HTTP'
,p_image_prefix => nvl(wwv_flow_application_install.get_static_plugin_file_prefix('WEB SOURCE TYPE','HTTP'),'')
,p_api_version=>1
,p_substitute_attributes=>true
,p_version_scn=>92497469
,p_subscribe_plugin_settings=>true
,p_help_text=>'Use a REST service as a REST Data Source.'
,p_version_identifier=>'1.0'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(1901267720643867)
,p_plugin_id=>wwv_flow_imp.id(1677862467038200)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_prompt=>'Pagination Type'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>false
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_null_text=>'No Pagination'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(1901523910653468)
,p_plugin_attribute_id=>wwv_flow_imp.id(1901267720643867)
,p_display_sequence=>10
,p_display_value=>'Page Size and Fetch Offset'
,p_return_value=>'FLEXIBLE'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Flexible pagination where the REST API allows to request a specific set of rows, using <em>page size</em> and <em>offset</em> ("start at row") parameters. URL typically look like the following example, which skips <strong>20</strong> and fetches t'
||'he next <strong>100</strong> rows:</p>',
'<pre>',
'http://hostname.example.com/path/to/rest_api?limit=100&offset=20',
'</pre>'))
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(1901988519660109)
,p_plugin_attribute_id=>wwv_flow_imp.id(1901267720643867)
,p_display_sequence=>20
,p_display_value=>'Page Size and Page Number'
,p_return_value=>'PAGE_NUMBER_FLEXIBLE_SIZE'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Pagination where the REST API allows to request a set of rows, using <em>page size</em> and <em>page number</em> parameters. URLs typically look like the following example which requests page number <strong>2</strong> with a page size of <strong>1'
||'00</strong>, which leads to rows 101 to 200 being returned.',
'</p>',
'<pre>',
'http://hostname.example.com/path/to/rest_api?size=100&page=2',
'</pre>'))
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(1902974368668773)
,p_plugin_attribute_id=>wwv_flow_imp.id(1901267720643867)
,p_display_sequence=>30
,p_display_value=>'Page Number'
,p_return_value=>'PAGE_NUMBER_FIXED_SIZE'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Pagination where the REST API allows to request a set of rows, using a <em>page</em> parameter. The Page Size is fixed and determined by the REST API. URLs typically look like the following example which requests page number <strong>2</strong>. If'
||' the REST API uses a fixed page size of <strong>20</strong>, rows 21 to 40 will be returned.',
'<pre>',
'http://hostname.example.com/path/to/rest_api?page=2',
'</pre>'))
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(3974584971018895)
,p_plugin_attribute_id=>wwv_flow_imp.id(1901267720643867)
,p_display_sequence=>40
,p_display_value=>'Page Size and Page Token'
,p_return_value=>'PAGE_TOKEN_FLEXIBLE_SIZE'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Pagination where the REST API allows to request a set of rows, using a combination of a <em>page token</em> and <em>page size</em> parameters. The token is used to retrieve the next set of rows, and is returned in the response body of the previous'
||' request. The page size determines the number of rows to return in each request. URLs typically look like the following example, which requests the next set of rows using the token <strong>ApEx=</strong> and a page size of <strong>100</strong>.',
'</p> ',
'<pre>',
'http://hostname.example.com/path/to/rest_api?token=ApEx=&limit=100',
'</pre>'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(1904445073685723)
,p_plugin_id=>wwv_flow_imp.id(1677862467038200)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>2
,p_display_sequence=>20
,p_prompt=>'Page Size URL Parameter'
,p_attribute_type=>'TEXT'
,p_is_required=>false
,p_display_length=>50
,p_max_length=>255
,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(1901267720643867)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'IN_LIST'
,p_depending_on_expression=>'FLEXIBLE,PAGE_NUMBER_FLEXIBLE_SIZE,PAGE_TOKEN_FLEXIBLE_SIZE'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Provide the URL parameter to specify the <em>page size</em> to be requested from the REST API. Typical values are <strong>limit</strong>, <strong>page_size</strong> or </strong>per_page</strong>.</p>',
'<p><em>Do not add this parameter within REST Data Source <strong>Parameters</strong></em>. &PRODUCT_NAME. will add it automatically when executing the HTTP request.</p>'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(1904796837692405)
,p_plugin_id=>wwv_flow_imp.id(1677862467038200)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>3
,p_display_sequence=>30
,p_prompt=>'Page Size Maximum'
,p_attribute_type=>'NUMBER'
,p_is_required=>false
,p_display_length=>10
,p_max_length=>10
,p_unit=>'rows'
,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(1901267720643867)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'IN_LIST'
,p_depending_on_expression=>'PAGE_NUMBER_FLEXIBLE_SIZE,FLEXIBLE,PAGE_TOKEN_FLEXIBLE_SIZE'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Provide the maximum amount of rows per page, which the REST API allows to fetch. &PRODUCT_NAME. will not attempt to request more rows per page.</p>',
'<p>Make sure that the REST API <em>actually returns</em> that amount of rows, since &PRODUCT_NAME. assumes a requested page to be the last page, if the response contains less rows than requested.</p>'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(1905045481696652)
,p_plugin_id=>wwv_flow_imp.id(1677862467038200)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>4
,p_display_sequence=>40
,p_prompt=>'Page Number URL Parameter'
,p_attribute_type=>'TEXT'
,p_is_required=>true
,p_display_length=>50
,p_max_length=>255
,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(1901267720643867)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'IN_LIST'
,p_depending_on_expression=>'PAGE_NUMBER_FLEXIBLE_SIZE,PAGE_NUMBER_FIXED_SIZE'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Provide the URL parameter to specify the <em>Page Number</em> to request from the REST API. A typical value is <strong>page</strong>.</p>',
'<p><em>Do not add this parameter within REST Data Source <strong>Parameters</strong></em>. &PRODUCT_NAME. will add it automatically when executing the HTTP request.</p>'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(1905385707699679)
,p_plugin_id=>wwv_flow_imp.id(1677862467038200)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>5
,p_display_sequence=>50
,p_prompt=>'Index of First Page'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'1'
,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(1901267720643867)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'IN_LIST'
,p_depending_on_expression=>'PAGE_NUMBER_FLEXIBLE_SIZE,PAGE_NUMBER_FIXED_SIZE'
,p_lov_type=>'STATIC'
,p_help_text=>'<p>Specify whether the REST API starts counting pages at index <strong>"0"</strong> or <strong>"1"</strong>.</p>'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(1905636932702605)
,p_plugin_attribute_id=>wwv_flow_imp.id(1905385707699679)
,p_display_sequence=>10
,p_display_value=>'1'
,p_return_value=>'1'
,p_is_quick_pick=>true
,p_help_text=>'The REST API refers to the first page as page <strong>1</strong>.'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(1906025829704631)
