,p_display_sequence=>20
,p_display_value=>'0'
,p_return_value=>'0'
,p_is_quick_pick=>true
,p_help_text=>'The REST API refers to the first page as page <strong>0</strong>.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(1906661765710861)
,p_plugin_id=>wwv_flow_imp.id(1677862467038200)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>6
,p_display_sequence=>60
,p_prompt=>'Fixed Page Size'
,p_attribute_type=>'NUMBER'
,p_is_required=>true
,p_display_length=>10
,p_max_length=>10
,p_unit=>'rows'
,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(1901267720643867)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'PAGE_NUMBER_FIXED_SIZE'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Provide the <em>page size</em> (number of rows per page), which is determined by the REST API.</p>',
'<p>Typically this information can be found in the documentation of the REST API. Make sure to specify the correct value here: if the value is not accurate, rows will be missing or duplicated when &PRODUCT_NAME. fetches data from the REST API.</p>'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(1906984049714159)
,p_plugin_id=>wwv_flow_imp.id(1677862467038200)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>7
,p_display_sequence=>70
,p_prompt=>'Row Offset URL Parameter'
,p_attribute_type=>'TEXT'
,p_is_required=>true
,p_display_length=>50
,p_max_length=>255
,p_unit=>'rows'
,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(1901267720643867)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'FLEXIBLE'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Provide the URL parameter to specify the <em>offset</em>, which denotes the rows to skip before the first row is returned.</p>',
'<p><em>Do not add this parameter within REST Data Source <strong>Parameters</strong></em>. &PRODUCT_NAME. will add it automatically when executing the HTTP request.</p>'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(1907222147716823)
,p_plugin_id=>wwv_flow_imp.id(1677862467038200)
