,p_depending_on_attribute_id=>wwv_flow_imp.id(1901267720643867)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'FLEXIBLE'
,p_lov_type=>'STATIC'
,p_help_text=>'<p>Choose whether the <strong>Offset</strong> parameter specifies the <em>Amount of Rows to Skip</em>, or the <em>First Row to Fetch</em>.</p>'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(1907577038717722)
