,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'NOT_NULL'
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>If a REST API returns the following JSON response:</p>',
'<pre>',
'{',
'    "items": [',
'         { // row 1 },',
'         { // row 2 },',
'         :',
'         { // row n } ',
'    ],',
'    "metadata": {',
'         "pagination": {',
'             "moreRows": true,',
'             "totalRows": 2712,',
'             "nextPage": 10 ',
'         } ',
'    } ',
'}',
'</pre>',
'<p>',
'The <strong>Has More Rows Selector</strong> is <strong>metadata.pagination.moreRows</strong>.',
'</p>'))
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>If the response REST API returns information about whether there are additional pages, provide the <em>selector</em> to extract this attribute here.</p>',
'<p>Specifying a <strong>Has More Rows Selector</strong> is not required, but it helps &PRODUCT_NAME. to save additional HTTP requests (which would return no data) when all data has already been fetched.</p>'))
);
wwv_flow_imp_shared.create_plugin_attribute(
