prompt --application/shared_components/plugins/item_type/geocoded_address
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(1700838675352758)
,p_plugin_type=>'ITEM TYPE'
,p_name=>'GEOCODED_ADDRESS'
,p_display_name=>'Geocoded Address'
,p_supported_component_types=>'APEX_APPLICATION_PAGE_ITEMS'
,p_image_prefix => nvl(wwv_flow_application_install.get_static_plugin_file_prefix('ITEM TYPE','GEOCODED_ADDRESS'),'')
,p_javascript_file_urls=>wwv_flow_string.join(wwv_flow_t_varchar2(
'#IMAGE_PREFIX#libraries/apex/#MIN_DIRECTORY#model#MIN#.js',
'#IMAGE_PREFIX#libraries/apex/#MIN_DIRECTORY#widget.tableModelViewBase#MIN#.js',
'#IMAGE_PREFIX#libraries/apex/#MIN_DIRECTORY#widget.tableModelView#MIN#.js',
'#IMAGE_PREFIX#libraries/apex/#MIN_DIRECTORY#widget.grid#MIN#.js',
'#IMAGE_PREFIX#libraries/apex/#MIN_DIRECTORY#widget.iconList#MIN#.js',
'#IMAGE_PREFIX#libraries/apex/#MIN_DIRECTORY#widget.miniMap#MIN#.js',
'#IMAGE_PREFIX#libraries/apex/#MIN_DIRECTORY#widget.geoCoder#MIN#.js'))
,p_api_version=>3
,p_standard_attributes=>'VISIBLE:SESSION_STATE:READONLY:SOURCE'
,p_substitute_attributes=>true
,p_version_scn=>7414340
,p_subscribe_plugin_settings=>true
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>This item type provides Geocoding (turning a postal address to a coordinate) functionality.<p>',
'<p>Geocoding is performed by <em>the browser</em> doing a REST request to the <strong>Oracle Elocation</strong> Geocoding Service (elocation.oracle.com). Thus the browser must be connected to the internet in order for geocoding to work.</p>',
'<p>Geocoding input data comes from other page items, which are mapped to address parts like Street, House Number, Postal Code or City. The Geocoder will show a popup window with a list of possible matches. After choosing a match, the item''s session s'
||'tate value will be the address coordinate in GeoJSON format. If <strong>Sanitize Address</strong> is enabled, address part page items will be overwritten with the sanitized values received from the Geocoding service.</p>',
'<p>For simpler use cases, the <strong>Unstructured Address</strong> mode allows to map only one text field or text area where end users enter address parts, separated by comma. In this case, the <strong>Sanitize Address</strong> mode is not available'
||'.</p>'))
);
wwv_flow_imp_shared.create_plugin_attr_group(
 p_id=>wwv_flow_imp.id(6282184372711753)
,p_plugin_id=>wwv_flow_imp.id(1700838675352758)
,p_title=>'Geocoding Input'
,p_display_sequence=>10
);
wwv_flow_imp_shared.create_plugin_attr_group(
 p_id=>wwv_flow_imp.id(6282574537711753)
,p_plugin_id=>wwv_flow_imp.id(1700838675352758)
,p_title=>'Geocoding Result'
,p_display_sequence=>20
);
