,p_substitute_attributes=>false
,p_version_scn=>72472659
,p_subscribe_plugin_settings=>true
,p_help_text=>'Process to insert, update, or delete a form region row(s).'
,p_version_identifier=>'1.0'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(3130191485054761)
,p_plugin_id=>wwv_flow_imp.id(3129968725049081)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_prompt=>'Target Type'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'REGION_SOURCE'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>'Select which row processing technique is performed to save data changes made to the Form Region.'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(3130418909057477)
,p_plugin_attribute_id=>wwv_flow_imp.id(3130191485054761)
,p_display_sequence=>10
,p_display_value=>'Region Source'
,p_return_value=>'REGION_SOURCE'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Inserts, updates, and deletes utilize the region source SQL Query .</p>',
'<p>Note - Ensure columns that are not insertable or updatable have <strong>Query Only</strong>  set to <code>Yes</code>, to exclude them from processing.</p>'))
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(3131111455059474)
,p_plugin_attribute_id=>wwv_flow_imp.id(3130191485054761)
,p_display_sequence=>20
,p_display_value=>'Table / View'
,p_return_value=>'TABLE'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Inserts, updates, and deletes utilize a different table or view to the one defined in the region source SQL Query.',
'For example, the SQL Query retrieves data from a table-join or non-undateable view and the DML processing needs to be performed against a single base table or updatable view.</p>',
'<p>Note - Ensure columns that are not insertable or updatable have <strong>Query Only</strong> set to <code>Yes</code>, to exclude them from processing.</p>'))
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(3131849869061275)
,p_plugin_attribute_id=>wwv_flow_imp.id(3130191485054761)
,p_display_sequence=>30
,p_display_value=>'PL/SQL Code'
,p_return_value=>'PLSQL_CODE'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Processing is based on custom PL/SQL code. This option allows you to execute any PL/SQL code to implement any data manipulation in the underlying database.</p>',
'<p>This option should be utilized when using database packages, such as table APIs or calls to RESTful Web Services, to implement business logic.</p>',
'<p>Note - The PL/SQL code will be called for each row that has been inserted, updated or deleted.</p>'))
