,p_display_sequence=>30
,p_display_value=>'PL/SQL Code'
,p_return_value=>'PLSQL_CODE'
,p_help_text=>'Custom PL/SQL code will be used to lock the rows until the transaction is committed.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(3136083157108563)
,p_plugin_id=>wwv_flow_imp.id(3129968725049081)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>7
,p_display_sequence=>70
,p_prompt=>'PL/SQL Code to Lock Row'
,p_attribute_type=>'PLSQL'
,p_is_required=>false
,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(3134090605099409)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'PLSQL_CODE'
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<pre>',
'declare',
'    l_dummy number;',
'begin',
'    select 1',
'      into l_dummy',
'      from emp',
'     where empno = :P1_EMPNO',
'       for update nowait;',
'end;',
'</pre>'))
,p_help_text=>'Enter the PL/SQL code to lock the database table rows to be updated and deleted.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(3136593347114047)
,p_plugin_id=>wwv_flow_imp.id(3129968725049081)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>8
,p_display_sequence=>80
,p_prompt=>'Return Primary Key(s) after Insert'
