,p_is_translatable=>false
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'If enabled, &PRODUCT_NAME. looks for an attribute "#name#_verified" (for example, "email_verified" for Attribute "email").',
'OpenID defines that the identity provider sends <code>"#name#_verified":false</code> for unverified "email" and "phone_number" attributes.',
'&PRODUCT_NAME. ignores such unverified attributes.',
'This will result in a failed authentication if "#name#" is the Username attribute.',
'</p><p>',
'If the identity provider lets attackers enter unverified data that the application uses for authentication,',
'they could impersonate other users in the application.',
'The "Verify Attributes" check prevents this.',
'</p>'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(388762589390412438)
,p_plugin_id=>wwv_flow_imp.id(15242808636946504)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>14
,p_display_sequence=>110
,p_prompt=>'Map Additional User Attributes To'
,p_attribute_type=>'TEXT'
,p_is_required=>false
,p_is_translatable=>false
,p_examples=>'G_EMAIL,G_PROFILE,G_PICTURE'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Provide a comma-separated list of application item names that the <em>Additional User Attributes</em> map to. For example, if you set',
'<ul>',
'<li>Additional User Attributes: email,profile,picture</li>',
'<li>Map Additional User Attributes To: G_EMAIL,G_PROFILE,G_PICTURE</li>',
'</ul>',
'then APEX automatically saves the attribute values in session state for the corresponding items.'))
);
end;
