,p_return_value=>'REGION_SOURCE'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Inserts, updates, and deletes utilize the region source SQL Query .</p>',
'<p>Note - Ensure columns that are not insertable or updatable have <strong>Query Only</strong>  set to <code>Yes</code>, to exclude them from processing.</p>'))
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(260819835191938290)
,p_plugin_attribute_id=>wwv_flow_imp.id(260819106949935652)
,p_display_sequence=>20
,p_display_value=>'Table / View'
,p_return_value=>'TABLE'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
