prompt --application/shared_components/plugins/authentication_type/custom
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(352953211423309033)
,p_plugin_type=>'AUTHENTICATION TYPE'
,p_name=>'CUSTOM'
,p_display_name=>'Custom'
,p_image_prefix => nvl(wwv_flow_application_install.get_static_plugin_file_prefix('AUTHENTICATION TYPE','CUSTOM'),'')
,p_api_version=>1
,p_standard_attributes=>'INVALID_SESSION:LOGIN_PAGE'
,p_substitute_attributes=>true
,p_version_scn=>72472667
,p_subscribe_plugin_settings=>true
,p_help_text=>'An authentication scheme that allows you to define your own PL/SQL Functions for determining user authentication.'
,p_version_identifier=>'1.0'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(353179625368369848)
,p_plugin_id=>wwv_flow_imp.id(352953211423309033)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_prompt=>'Sentry Function Name'
,p_attribute_type=>'TEXT'
,p_is_required=>false
,p_is_translatable=>false
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Specify PL/SQL code returning a boolean value, within the ''PL/SQL Code'' -</p>',
'<pre>',
'function sentry_basic_auth',
'return boolean',
'is',
'    c_auth_header   constant varchar2(4000) := owa_util.get_cgi_env(''AUTHORIZATION'');',
'    l_user_pass     varchar2(4000);',
'    l_separator_pos pls_integer;',
'begin',
'    if apex_application.g_user <> ''nobody'' then',
'        return true;',
'    end if;',
'',
'    if c_auth_header like ''Basic %'' then',
'        l_user_pass := utl_encode.text_decode (',
'                           buf      => substr(c_auth_header, 7),',
'                           encoding => utl_encode.base64 );',
'        l_separator_pos := instr(l_user_pass, '':'');',
'        if l_separator_pos > 0 then',
'            apex_authentication.login (',
'                p_username => substr(l_user_pass, 1, l_separator_pos-1),',
'                p_password => substr(l_user_pass, l_separator_pos+1) );',
'            return true;',
'        end if;',
'    end if;',
'',
'    return false;',
'end sentry_basic_auth;',
'</pre>',
'<p>Specify a PL/SQL Database function - </p>',
'<pre>',
'sentry_basic_auth',
'</pre>'))
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Enter the name of a function that is executed by the &PRODUCT_NAME. engine at the start of any request made to the engine, such as before each page is shown or processed, or an AJAX request is issued. ',
'It can be defined in the authentication''s PL/SQL Code, within a package or as a stored function.</p>',
'<p>If this function returns false (indicating perhaps that the user isn''t logged in),this marks the session as not valid and the <em>Invalid Session Procedure</em> will be invoked.',
'After that, &PRODUCT_NAME. redirects to the URL defined in ''Session Not Valid > Go To''.',
'If the value of this field is empty,',
'an internal default sentry is called that tries to establish a valid session by comparing the session ID in the URL and the session information in the authentication scheme cookie (with a fall-back to the &PRODUCT_NAME. Builder cookie, if that fails)'
||'.</p>'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(551983430308015470)
,p_plugin_id=>wwv_flow_imp.id(352953211423309033)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>2
,p_display_sequence=>20
,p_prompt=>'Invalid Session Procedure Name'
,p_attribute_type=>'TEXT'
,p_is_required=>false
,p_is_translatable=>false
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<pre>',
'procedure invalid_session_basic_auth',
'is',
'begin',
'    owa_util.status_line (',
'        nstatus       => 401,',
'        creason       => ''Basic Authentication required'',',
'        bclose_header => false);',
'    htp.p(''WWW-Authenticate: Basic realm="protected realm"'');',
'    apex_application.stop_apex_engine;',
'end invalid_session_basic_auth;',
'</pre>'))
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Enter the name of a PL/SQL procedure that gets called if an invalid session has been detected.</p>',
'',
'<p>It can reference a function of the anonymous PL/SQL code block, a package function or a stand alone function in the database. For example: <code>invalid_session_basic_auth</code></p>',
'',
'<p>When referencing a database PL/SQL package or stand alone function, you can use the <code>#OWNER#</code> substitution string to reference the parsing schema of the current application. For example: <code>#OWNER#.invalid_session_basic_auth</code></'
||'p>'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(353293115026395181)
,p_plugin_id=>wwv_flow_imp.id(352953211423309033)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>3
,p_display_sequence=>30
,p_prompt=>'Authentication Function Name'
,p_attribute_type=>'TEXT'
,p_is_required=>false
,p_is_translatable=>false
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Enter the following code in the ''PL/SQL Code'' textarea</p>',
'<pre>',
'function my_authentication (',
'    p_username in varchar2,',
'    p_password in varchar2 )',
'    return boolean',
'is',
'    l_user my_users.user_name%type := upper(p_username);',
'    l_id   my_users.id%type;',
'    l_hash my_users.password_hash%type;',
'begin',
'    begin',
'        select id  , password_hash',
'          into l_id, l_hash',
'          from my_users',
'         where user_name = l_user;',
'    exception when no_data_found then',
'        l_hash := ''-invalid-'';',
'    end;',
'',
'    return l_hash = rawtohex(sys.dbms_crypto.hash (',
'                        sys.utl_raw.cast_to_raw (',
'                            p_password||l_id||l_user ),',
'                        sys.dbms_crypto.hash_sh512 ));',
'end;',
'</pre>',
'',
'<p>and <code>my_authentication</code> as ''Authentication Function''.'))
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Specify the name of the function that will verify the user''s username and password, after they were entered on a login page.',
'If you enter nothing, you allow any username/password to succeed.',
'The function itself can be defined in the authentication''s ''PL/SQL Code'' textarea, within a package or as a stored function.</p>',
'',
'<p>This function must return a boolean to the login procedure that calls it. It has 2 input parameters ''p_username'' and ''p_password'' that can be used to access the values an end user entered on the login page.</p>'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(353301225415398269)
,p_plugin_id=>wwv_flow_imp.id(352953211423309033)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>4
,p_display_sequence=>40
,p_prompt=>'Post Logout Procedure Name'
,p_attribute_type=>'TEXT'
,p_is_required=>false
,p_is_translatable=>false
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Enter the following code in the ''PL/SQL Code'' textarea</p>',
'<pre>',
'procedure my_post_logout',
'is',
'begin',
'    insert into logout_log (',
'        application_id,',
'        session_id,',
'        logout_time,',
'        user_name',
'    ) values (',
'        :APP_ID,',
'        :APP_SESSION,',
'        sysdate,',
'        :APP_USER );',
'end;',
'</pre>',
'',
'<p>and <code>my_post_logout</code> as ''Post Logout Procedure''.</p>'))
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'The name of the procedure that gets called after the end user clicked on the logout URL. It can be used for logging.',
'The procedure itself can be defined in the authentication''s ''PL/SQL Code'' textarea, within a package or as a stored function.'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(629094915193552126)
,p_plugin_id=>wwv_flow_imp.id(352953211423309033)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>5
,p_display_sequence=>50
,p_prompt=>'Enable Legacy Authentication Attributes'
,p_attribute_type=>'CHECKBOX'
,p_is_required=>false
,p_default_value=>'N'
,p_is_translatable=>false
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Additional authentication attributes become visible if this select list is set to "Yes".',
'They are mainly relevant for custom authentications that have been ported from &PRODUCT_NAME. 4.0 and earlier.'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(629174621211563368)
,p_plugin_id=>wwv_flow_imp.id(352953211423309033)
