wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(3010482773505284)
,p_plugin_id=>wwv_flow_imp.id(1630055805138100682)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>7
,p_display_sequence=>70
,p_static_id=>'allow_custom_html'
,p_prompt=>'Allow Custom HTML'
,p_attribute_type=>'CHECKBOX'
,p_is_required=>false
,p_default_value=>'N'
,p_is_translatable=>false
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>For advanced usage only.</p>',
'<p>As a preferred alternative, embedding snippets of custom HTML can also be done via the "HTML Embed" functionality available in the "Full" Toolbar.</p>',
'<p>Unless necessary, this setting should be left disabled, as it is only meant to provide backwards compatibility with HTML generated by CKEditor4 or HTML hand-crafted by end users.</p>',
'<p>This setting controls whether the "General HTML Support" ("GHS") and "Source Editing" library plugins will be enabled or not. "Source Editing" offers the ability to manually change the underlying HTML, while General HTML Support allows for HTML fe'
||'atures that are not explicitly supported by any other dedicated library plugin. For example, HTML elements like <code>iframe</code> or <code>video</code>, or custom HTML atrributes like <code>id</code>, if added via the "Source Editing" functionality'
||', would normally be stripped away unless this attribute is enabled.</p>',
'<p>Under the hood, the General HTML Support plugins would be configured as follows:',
'<pre><code>htmlSupport: {',
'    allow: [ {',
'        name: /.*/,',
'        attributes: true,',
'        classes: true,',
'        styles: true',
'    } ]',
'}</code></pre></p>',
'<p>For more granular control, it is recommended to leave this setting off, and instead configure it via the Initialization JavaScript Function. For example:',
'<pre><code>function( options ) {',
'',
'    options.editorOptions.extraPlugins.push (',
'        CKEditor5.sourceEditing.SourceEditing,',
'        CKEditor5.htmlSupport.GeneralHtmlSupport,',
'        CKEditor5.htmlSupport.HtmlComment',
'    );',
'',
'    options.editorOptions.toolbar.items.push( "sourceEditing" );',
'',
'    options.editorOptions.htmlSupport = {',
'        allow: [ {',
'            name: /.*/,',
'            attributes: true,',
'            classes: true,',
'            styles: true',
'        } ]',
'    };',
'',
'    return options;',
'}</code></pre></p>'))
);
wwv_flow_imp_shared.create_plugin_std_attribute(
 p_id=>wwv_flow_imp.id(3112575602612766963)
,p_plugin_id=>wwv_flow_imp.id(1630055805138100682)
,p_name=>'INIT_JAVASCRIPT_CODE'
,p_is_required=>false
,p_depending_on_has_to_exist=>true
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<pre><code>function(options){',
'    // disable the Autoformat feature',
'    options.editorOptions.removePlugins.push( "Autoformat" );',
'    // apply a custom toolbar',
'    options.editorOptions.toolbar = [ "heading", "bulletedList", "numberedList", "fontSize", "undo", "redo" ];',
'    return options;',
'}</code></pre>'))
,p_help_text=>'Enter a JavaScript function to override the standard editor configuration.'
);
end;
/
