,p_is_translatable=>false
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Whether to apply syntax highlighting for specific Markdown elements such as bold, italics, code blocks, etc.</p>',
'<p>Highlighting will only take place for content under 4000 characters in length.</p>'))
);
wwv_flow_imp_shared.create_plugin_std_attribute(
 p_id=>wwv_flow_imp.id(55495142284465026)
,p_plugin_id=>wwv_flow_imp.id(8511644498934019458)
,p_name=>'INIT_JAVASCRIPT_CODE'
,p_is_required=>false
,p_depending_on_has_to_exist=>true
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
